from pathlib import Path
import json
B=Path(__file__).resolve().parent;S=[];C={}
def add(k,title,text,form,notes):S.append(dict(id=k,title=title,text=text));C[k]=dict(form=form,notes=notes)
add('hello','走到一半，前面封了怎么办？','大家好，我是硅宝。上一集学会复用搜索，老板今天让我边走边算。我刚走到一半，前面的通道就封了。我说，起点都变了，草稿还能用吗？老板说，你只是往前走了几步，别又把整个办公室重新装修。今天研究 D 星 Lite，移动中的增量重规划。',[r'\text{move}+\text{repair}'],['第24集 · 动态环境下的实时规划','D* Lite｜移动中的重规划','已发现的变化，不是未来运动预测'])
add('bridge','LPA*的起点固定，这次机器人动了','上一集的 L P A 星，起点和终点固定。这次目标不动，机器人的当前位置不断改变。一个直接办法是每走一步，就从新位置重新运行 A 星。但如果地图大部分没变，我们希望保留旧的搜索状态，只补必要的计算。这就是今天的出发点。',[r'\text{LPA*}\to\text{D* Lite}'],['固定目标，当前位置移动','保留g、rhs和队列','经典算法，非最新算法或官方库复现'])
add('setup','两组实验：受控变化与有限视野导航','我们仍用二十三乘十五的四邻接栅格，相邻边至少花一个代价。第一组控制机器人移动和地图更新，方便看清机制。第二组才加入有限视野：传感器看到周围两格，未知地方先假设能走。每次先观察和规划，再离散走一步；没有模拟惯性、刹车和连续时间。',[r'c(u,v)\geq1',r'h(a,b)=|x_a-x_b|+|y_a-y_b|'],['受控实验与感知导航分开标注','理想方形范围传感，无遮挡建模','每步规划后再移动，非真机'])
add('reverse','关键转向：从目标向当前位置反向维护','如果从当前位置出发计算，当前位置一变，很多起点代价的含义也跟着变。D 星 Lite 反过来，从目标维护到目标的代价估计。目标没变，这套信息更容易继续使用。搜索传播方向反过来了，机器人实际还是从当前位置往目标走，可不是倒着开回去。',[r'rhs(T)=0',r'g(u):\ \text{cost-to-go estimate}'],['g现在估计从节点到目标的代价','与上一集起点代价的含义不同','反向搜索，不是机器人倒着走'])
add('rhs','rhs这次看后继，别把方向照抄反了','对目标，一步前瞻值固定为零；对其他节点，查看所有可以走向的后继，把当前边代价加上后继的目标代价估计，再取最小值。上一集看前驱，这一集看后继。无向栅格里邻居集合碰巧一样，但写有向图时，方向写反就真会翻车。',[r'rhs(T)=0',r'rhs(u)=\min_{v\in Succ(u)}[c(u,v)+g(v)]'],['rhs使用后继的目标代价','边u→v改变，先更新rhs(u)','不直接照搬LPA*更新终点的方向'])
add('hand','独立手算：封路让旧估计过于乐观','看一个独立小图。节点 V 可以去甲或乙，它们的目标代价估计是二和三，两条边分别花一和二，所以 V 报三。现在去甲的边从一涨到五，新的报价变成二加五与三加二中的较小值，也就是五。旧估计三还留着，需要撤销，再让依赖它的前驱重新报价。',[r'rhs_{old}(V)=\min(1+2,2+3)=3',r'rhs_{new}(V)=\min(5+2,2+3)=5'],['独立手算，不对应栅格计数','g<rhs：先撤销过时的低估','向前驱传播目标代价变化'])
add('branches','账目修复的两种分支','如果旧估计比新报价大，就接受更低的报价，并更新前驱。如果旧估计比新报价小，就先把旧估计撤为无穷大，再更新自身和前驱。只有两本账不一致的节点，才需要留在队列里。不是把每个节点全算一遍，也不是只改封路那一格。',[r'g(u)>rhs(u)\Rightarrow g(u)\leftarrow rhs(u)',r'g(u)<rhs(u)\Rightarrow g(u)\leftarrow\infty'],['接受更低报价，或者撤销旧低估','目标距离向前驱传播','保留与当前查询有关的不一致节点'])
add('key','当前位置一动，队列优先级怎么办？','难点来了。队列关键字里要用当前位置到节点的启发距离，当前位置一动，很多节点的优先级都可能变。难道要把整条队列重新排序？D 星 Lite 加了一个偏移量，读作 k m。关键字第一项，是两本账的较小值，加启发距离，再加这个偏移量；第二项仍是两本账的较小值。',[r'm(u)=\min(g(u),rhs(u))',r'K(u)=[m(u)+h(S,u)+k_m,\ m(u)]'],['关键字按两项字典序比较','h必须满足相应一致性条件','km不是路径代价，也不是行驶时间'])
add('km','km：让旧关键字仍能作为下界','重新规划时，把上次记录的位置到当前位置的启发距离，加进偏移量，再记录新位置。在一致启发的条件下，旧队列关键字仍可作为新的下界。取出节点时再比较：如果旧关键字小于当前关键字，就按新关键字放回队列。这样延迟更新，不用因为移动就立即全队列重排。',[r'k_m\leftarrow k_m+h(S_{last},S)',r'K_{old}<K_{new}\Rightarrow\text{reinsert}'],['本实现每个规划查询记录一次位置','旧堆项过期清理与关键字更新分开计数','保持g/rhs/队列，不每步初始化'])
add('keyhand','独立手算：向前走，不是所有关键字都不变','独立算一下。旧位置是一，七，新位置是五，七，偏移量增加四。某节点在十，七，较小账目为十，关键字第一项从十九变成十加五加四，仍是十九。另一个节点在零，七，第一项却从十一变成十九。所以不能说所有关键字都没变；正确做法是取出时检查，必要时重新入队。',[r'10+9+0=10+5+4=19',r'10+1+0=11<10+5+4=19'],['两个独立节点说明关键字不同变化','旧值可作下界，不代表旧值都精确','代价涨跌仍需正常修复'])
add('stop','什么时候算够了，怎样选下一步？','基础版停止条件是：当前位置两本账一致，而且队首关键字不小于当前位置关键字。不是等队列彻底清空。然后选择边代价加后继目标估计最小的一步。本集代价都为正，最终路径还要独立检查邻接、障碍和代价。如果当前位置代价是无穷大，就报告当前已知地图无路，停止移动。',[r'g(S)=rhs(S),\quad TopKey(U)\geq K(S)',r'v^*=\arg\min_v[c(S,v)+g(v)]'],['停止条件针对基础版实现','无路时不强行迈出一步','剩余旧队列留给后续修复'])
add('advance','真实实验：走七步，旧结果还能用','开始跑受控实验。初始最短代价二十，两种算法都扩展二十一次。机器人沿原路线向前七步，来到八，七。地图没变，剩余代价十三。D 星 Lite 本次没有有效扩展，重跑 A 星扩展十四次。但零扩展不等于零耗时，路径提取、查询检查和程序调用仍然要做。',[r'C:20\to13',r'N_{D*Lite}=0,\quad N_{A*}=14'],['实际当前位置：(8,7)，km=7','0次有效扩展，不是0毫秒','同一当前图分别核对最短代价'])
add('closure','前面三格封闭：旧路线失效，局部修复','现在把前面十这一列的三格封住，旧路线确实穿过了它们。把相关边的代价更新完，再更新这些有向边起点的一步报价。修复后剩余代价十七，D 星 Lite 有效扩展六十四次，重跑 A 星七十一次；另有十三次旧关键字更新。这些工作不能偷偷从账本里抹掉。',[r'C_{remaining}=17',r'N_{D*Lite}=64,\quad N_{A*}=71'],['真实封路：(10,6)、(10,7)、(10,8)','本查询另有13次延迟关键字更新','紫线是失效旧路线，金线是修复路线'])
add('reopen','绕行后开门，结果未必立刻更短','沿修复路线再走两步，来到八，五。随后三格重新开放，算法接受地图更新并修复。这个位置的最短剩余代价仍然是十五，没有继续下降。环境变好了，不代表你现在所在的位置一定因此受益；不能为了讲故事，就把每次开门都演成抄近路。',[r'S=(8,5),\quad k_m=9',r'C_{before}=C_{after}=15'],['前进两步时有效扩展0次','开门修复6次，对照A*42次','最短代价没变，搜索状态仍有更新'])
add('failure','整列封死：停下，再演示开门恢复','接着把十二这一整列封闭，当前图没有通路。算法返回无路，小车停在原地，不播放一条穿墙的动画。只重新打开十二，七这一格，修复后恢复代价十五的可行路线。这段是受控地图更新，整列变化来自外部地图通知，不伪装成两格视野一次看见了整堵墙。',[r'C=\infty\Rightarrow\text{stop}',r'\text{open gate}\Rightarrow C=15'],['整列变化：外部地图更新实验','无路122次扩展；开门恢复13次','只在有效路径重新出现后继续'])
add('sensor','有限视野导航：只按看到的地图规划','第二组换成真正逐步揭示的地图。真实障碍固定，机器人起初不知道，周围两格范围内观察到的障碍才加入已知图。未知格先当可通行，每次从当前位置重算，再走一个经过检查的相邻格。这次实际走了三十四步，到达目标；每次已知图的最短代价，都与独立算法一致。',[r'\text{sense}\to\text{repair}\to\text{move}',r'34\ \text{moves},\quad35\ \text{queries}'],['种子7，理想方形范围半径2','未知假设可通行，障碍真实静止','不是预先知道整图的全程最短路径'])
add('verify','验收：对照代价，也检查每一步','另外用三个随机种子，各做五十次混合测试，包含移动起点、封路、重开和软代价变化。每次把当前图交给从头运行的 A 星，以及独立的狄克斯特拉，再核对最短代价。路径逐段检查，不靠画面看着顺来验收。一百五十次更新通过，只说明这些测试通过，不是普遍正确性的证明。',[r'3\times50=150\ \text{updates}',r'C_{D*Lite}=C_{A*}=C_{Dijkstra}'],['同一当前图与当前位置，逐次复核','150次混合更新不是150个独立环境','有限测试与论文理论保证分开'])
add('cost','实时性要算总账，别只盯扩展次数','本集比较的是有效扩展、邻居扫描、队列操作等工作量，不据此宣布快了多少倍。实际部署还要计算感知、地图更新、路径提取与执行延迟。实时规划更要设定时间预算，统计尾部耗时和超时后的处理。D 星 Lite 本身没有承诺任意地图都能在固定毫秒内完成。',[r'\text{expansions}\neq\text{runtime}',r'T_{loop}=T_{sense}+T_{plan}+T_{execute}'],['纯Python教学实现，不做硬实时结论','地图更新、队列与路径提取都有成本','正确结果也可能来得太晚'])
add('boundary','会重规划，不等于会预测移动障碍','老板问，那行人横穿过来，也解决了？还没有。这里解决的是已经发现的地图变化，维护当前图上的最短路线。行人两秒后在哪儿、机器人什么时候经过、能不能及时刹住，都不在这张只有位置的图里。把每一帧障碍当静态再重算，仍可能错过时间冲突。',[r'\text{map repair}\neq\text{time avoidance}'],['没有未来轨迹、时间维或动力学','未知地图导航不等于全知最优','移动障碍需要后续时空或预测方法'])
add('close','下一集：时间不够，先交一份能用的答案','今天记住三件事：从目标反向维护，修复不一致节点，用偏移量处理当前位置移动。旧草稿能留下，但不能拿旧答案冒充新地图。下一集研究时间预算：老板只给很短时间，能不能先交一条质量有界的路线，再边用边改？我们接着讲 A R A 星和 A D 星。',[r'\text{reuse}\to\text{repair}\to\text{act}'],['D* Lite：当前已知图上的增量重规划','下一集：ARA* → AD*','讲义与自写实验同步保留'])
(B/'lesson.json').write_text(json.dumps(S,ensure_ascii=False,indent=2));(B/'cards.json').write_text(json.dumps(C,ensure_ascii=False,indent=2));(B/'narration.txt').write_text('\n\n'.join(x['text']for x in S));print(len(S),'chapters',sum(len(x['text'])for x in S),'characters')
